{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine sulfate oral bioavailability was 80.5% in healthy subjects after oral versus intravenous administration, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Apricitabine oral bioavailability was reported as 73–80% in healthy subjects and HIV-1 patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Morphine absolute oral bioavailability was 23.8 ± 4.9% after a 10 mg immediate-release oral dose versus IV in non-obese subjects, at or above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred quantitative records report oral bioavailability values at or above 20%, with most well above the threshold, supporting a high absolute oral bioavailability prediction.",
  "evidence_gaps": [
    "Molecule 4 contains records for both pethidine/meperidine and morphine; the inconsistent identity was discounted, leaving pethidine/meperidine records as the basis.",
    "Some records are qualitative or unspecified in bioavailability type, but the quantitative absolute and systemic availability records are consistent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

